-- Blocks UPDATE/DELETE on append-only (immutable) tables.
CREATE OR REPLACE FUNCTION forbid_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'table % is append-only', TG_TABLE_NAME USING ERRCODE = '55000';
END $$;

CREATE OR REPLACE FUNCTION touch_row() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  NEW.row_version := OLD.row_version + 1;
  RETURN NEW;
END $$;

-- customer_action: Audit trail of customer actions through the channel, including object-level denials and step-up refusals
CREATE TABLE customer_action (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  customer_id                  uuid NOT NULL,
  action                       varchar(64) NOT NULL,
  object_type                  varchar(40),
  object_id                    uuid,
  outcome                      varchar(40) NOT NULL CHECK (outcome IN ('SUCCEEDED', 'DENIED', 'STEP_UP_REQUIRED', 'FAILED')),
  error_code                   varchar(64),
  result_id                    uuid,
  auth_age_seconds             integer,
  acr                          varchar(64),
  channel                      varchar(16),
  ip_address                   inet,
  user_agent                   varchar(255)
);
COMMENT ON TABLE customer_action IS 'Audit trail of customer actions through the channel, including object-level denials and step-up refusals';
COMMENT ON COLUMN customer_action.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN customer_action.tenant_id IS 'Owning tenant; enforced by row-level security';
